import { randomUUID } from "node:crypto";

export type Priority = 0 | 1 | 2; // 0 critical, 1 normal, 2 bulk

export interface Task<T = unknown> {
  id: string;
  key?: string;                       // idempotency / single-flight key
  priority: Priority;
  run(payloadCtx: { signal: AbortSignal }): Promise<T>;
}

interface Envelope {
  id: string;
  key?: string;
  priority: Priority;
  runAt: number;
  attempts: number;
  maxAttempts: number;
  deadlineMs: number;
  fn: Task["run"];
  settle?: (r: { ok: boolean; value?: unknown; error?: Error }) => void;
}

const now = () => Date.now();
const jitter = (ms: number, pct = 0.2) =>
  ms * (1 - pct + Math.random() * pct * 2);

// ---- tiny min-heap on (priority, runAt) ------------------------------------
class Heap<T> {
  private a: T[] = [];
  constructor(private lt: (x: T, y: T) => boolean) {}
  get size() { return this.a.length; }
  push(x: T) {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.lt(a[i], a[p])) [a[i], a[p]] = [a[p], a[i]], i = p;
      else break;
    }
  }
  pop(): T | undefined {
    const a = this.a;
    if (!a.length) return;
    const top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.lt(a[l], a[m])) m = l;
        if (r < a.length && this.lt(a[r], a[m])) m = r;
        if (m === i) break;
        [a[i], a[m]] = [a[m], a[i]];
        i = m;
      }
    }
    return top;
  }
}
