// auto-loop.ts — autonomous execution loop: bounded queue + cadence drainer + fail-safes
import { randomUUID } from "node:crypto";

export type Priority = 0 | 1 | 2; // 0=critical 1=normal 2=bulk

export interface Ctx { signal: AbortSignal }

export type Outcome = { ok: boolean; value?: unknown; error?: Error };

export interface Receipt {
  accepted: boolean;
  id?: string;
  reason?: "saturated" | "duplicate-key" | "shutting-down";
  /** Resolves (never rejects) with the final outcome. Awaiting is OPTIONAL. */
  done?: Promise<Outcome>;
}

export interface LoopOptions {
  batchSize?: number;         // max claims per tick                (16)
  concurrency?: number;       // max simultaneous jobs              (8)
  maxSize?: number;           // queued-envelope bound              (10_000)
  baseIntervalMs?: number;    // fastest heartbeat                  (250)
  maxIdleIntervalMs?: number; // idle-backoff ceiling              (10_000)
  sweepIntervalMs?: number;   // maintenance sweep                  (30_000)
  jobTimeoutMs?: number;      // default per-attempt deadline       (30_000)
  maxAttempts?: number;       // attempts before dead-letter        (5)
  breakerCooldownMs?: number; // breaker open period                (5_000)
  onDead?: (job: { id: string; key?: string }, err: Error) => void;
}

interface Env {
  id: string; key?: string; priority: Priority;
  runAt: number; attempts: number; maxAttempts: number; deadlineMs: number;
  fn: (ctx: Ctx) => Promise<unknown>;
  settle: (o: Outcome) => void;
}

const sleep = (ms: number) => new Promise<void>(r => setTimeout(r, ms).unref?.());
const jitter = (ms: number, pct = 0.2) => ms * (1 - pct + Math.random() * pct * 2);

class Heap<T> {
  private a: T[] = [];
  constructor(private lt: (x: T, y: T) => boolean) {}
  get size() { return this.a.length; }
  peek() { return this.a[0]; }
  push(v: T) {
    const a = this.a; a.push(v);
    for (let i = a.length - 1; i > 0;) {
      const p = (i - 1) >> 1;
      if (!this.lt(a[i], a[p])) break;
      [a[i], a[p]] = [a[p], a[i]]; i = p;
    }
  }
  pop(): T | undefined {
    const a = this.a; if (!a.length) return;
    const top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      for (let i = 0;;) {
        const l = 2*i+1, r = l+1; let m = i;
        if (l < a.length && this.lt(a[l], a[m])) m = l;
        if (r < a.length && this.lt(a[r], a[m])) m = r;
        if (m === i) break;
        [a[i], a[m]] = [a[m], a[i]]; i = m;
      }
    }
    return top;
  }
}

export class AutoLoop {
  private readonly o: Required<LoopOptions>;
  private ready   = new Heap<Env>((a,b) => a.priority !== b.priority ? a.priority < b.priority : a.runAt < b.runAt);
  private delayed = new Heap<Env>((a,b) => a.runAt < b.runAt);
  private inflight = new Map<string, AbortController>();
  private keyHolds = new Map<string, number>();   // key -> live envelopes (pending+retrying+running)
  private dlq: { job: { id: string; key?: string; attempts: number }; error: Error; at: number }[] = [];
  private outcomes: boolean[] = [];               // sliding window for the breaker
  private hb?: ReturnType<typeof setInterval>;
  private sweeper?: ReturnType<typeof setInterval>;
  private draining = false; private stopped = false; private wakeQueued = false;
  private idleStreak = 0; private openUntil = 0; private lastTick = 0;
  private c = { accepted: 0, rejected: 0, done: 0, retried: 0, dead: 0 };

  constructor(opts: LoopOptions = {}) {
    this.o = {
      batchSize: 16, concurrency: 8, maxSize: 10_000,
      baseIntervalMs: 250, maxIdleIntervalMs: 10_000, sweepIntervalMs: 30_000,
      jobTimeoutMs: 30_000, maxAttempts: 5, breakerCooldownMs: 5_000,
      onDead: opts.onDead ?? (() => {}),
      ...opts,
    } as Required<LoopOptions>;
  }

  /* ---- lifecycle ---------------------------------------------------- */

  start() {
    if (this.hb || this.stopped) return;
    this.lastTick = Date.now();
    this.reschedule();
    this.sweeper = setInterval(() => this.sweep(), this.o.sweepIntervalMs);
    this.sweeper.unref?.();
  }

  async stop({ drain = true, graceMs = 10_000 } = {}) {
    this.stopped = true;
    clearInterval(this.hb); clearInterval(this.sweeper);
    const deadline = Date.now() + graceMs;
    while (drain && this.inflight.size && Date.now() < deadline) await sleep(20);
    for (const ac of this.inflight.values()) ac.abort(new Error("shutdown"));
    await sleep(50); // let aborts propagate
    return { ...this.c, abandoned: this.inflight.size,
             dropped: this.ready.size + this.delayed.size, dlq: this.dlq.length };
  }

  /* ---- producer API: synchronous, bounded, never awaits ------------- */

  enqueue<T>(fn: (ctx: Ctx) => Promise<T>, opts: {
    priority?: Priority; key?: string; delayMs?: number;
    deadlineMs?: number; maxAttempts?: number;
  } = {}): Receipt {
    const priority = opts.priority ?? 1;
    const delayMs = opts.delayMs ?? 0;
    if (this.stopped)                                            return this.bounce("shutting-down");
    if (opts.key && (this.keyHolds.get(opts.key) ?? 0) > 0)      return this.bounce("duplicate-key");
    if (this.ready.size + this.delayed.size >= this.o.maxSize)   return this.bounce("saturated");

    const env: Env = {
      id: randomUUID(), key: opts.key, priority, runAt: Date.now() + delayMs,
      attempts: 0,
      maxAttempts: opts.maxAttempts ?? this.o.maxAttempts,
      deadlineMs: opts.deadlineMs ?? this.o.jobTimeoutMs,
      fn: fn as (ctx: Ctx) => Promise<unknown>,
      settle: () => {},
    };
    const done = new Promise<Outcome>(res => { env.settle = res; });

    if (opts.key) this.keyHolds.set(opts.key, (this.keyHolds.get(opts.key) ?? 0) + 1);
    delayMs > 0 ? this.delayed.push(env) : this.ready.push(env);
    this.c.accepted++;
    this.wake();
    return { accepted: true, id: env.id, done };
  }

  /* ---- the drainer --------------------------------------------------- */

  private tick() {
    if (this.stopped || this.draining) return;
    this.draining = true;
    this.lastTick = Date.now();
    try {
      if (Date.now() < this.openUntil) return;                 // breaker: stand down
      this.promote();
      const claimed: Env[] = [];
      while (claimed.length < this.o.batchSize &&
             this.inflight.size < this.o.concurrency && this.ready.size) {
        const env = this.ready.pop()!;
        env.attempts++;
        this.inflight.set(env.id, new AbortController());
        claimed.push(env);
      }
      if (!claimed.length) {                                   // idle → stretch the cadence
        this.idleStreak = Math.min(this.idleStreak + 1, 10);
      } else {
        this.idleStreak = 0;
        for (const env of claimed) this.execute(env);
      }
      this.reschedule();                                       // adapt heartbeat to load
    } finally {
      this.draining = false;
    }
  }

  private execute(env: Env) {
    const ac = this.inflight.get(env.id)!;
    const deadlineTimer = setTimeout(() => ac.abort(new Error("deadline")),
